class Node:    def __init__(self, value):        self.value = value        self.left = None        self.right = None        self.parent = Noneclass Splay_tree:    def __init__(self):        self.root = None # Корень дерева    def insert(self, value):        new_node = Node(value)        if self.root is None: # Если в нашей структуре нет данных, создаёт дерево            self.root = new_node            return        current = self.root        parent = None        #Поиск родителя для привязки:        while current is not None:            parent = current            #Это обычное бинарное дерево, слева меньше, справа больше            if value < current.value: #                current = current.left            elif value > current.value:                current = current.right            else:                return        #Привязываем новый узел к родителю        new_node.parent = parent        if value < parent.value:            parent.left = new_node        else:            parent.right = new_node        self._splay(new_node)    def _splay(self, node):        current = node        while current.parent is not None:            parent = current.parent            grandpa = current.parent.parent            if grandpa is None: #ZIG (один поворот)                if current == parent.left:                    self._right_rotate(current)                else:                    self._left_rotate(current)            else:                if current == parent.left and parent == grandpa.left: # ZIG-ZIG оба левые                    self._right_rotate(parent)                    self._right_rotate(current)                elif current == parent.right and parent == grandpa.right: # ZIG-ZIG оба правые                    self._left_rotate(parent)                    self._left_rotate(current)                elif current == parent.right and parent == grandpa.left: # ZIG-ZAG правый-левый                    self._left_rotate(current)                    self._right_rotate(current)                else: # ZIG-ZAG левый-правый                    self._right_rotate(current)                    self._left_rotate(current)        self.root = node    def _right_rotate(self,node):        parent = node.parent        current = node        if parent is None: return        #Передаём правого ребёнка current к родителю и меняем местами current и родителя        parent.left = current.right # Сын current меньше родителя current, сый уйдёт в левую ветку        if current.right is not None:            current.right.parent = parent        current.parent = parent.parent        # Назначения current сыном у деда        if parent.parent is None: # Если деда не было, значит родитель был корнем, делаем current корнем            self.root = current        elif parent == parent.parent.left:            parent.parent.left = current # Если родитель был левым ребенком то current становится тоже левым ребёнком, иначе правым        else:            parent.parent.right = current        current.right = parent        parent.parent = current    def _left_rotate(self, node):        parent = node.parent        current = node        if parent is None: return        # Передаём левого ребёнка current к родителю и меняем местами current и родителя        parent.right = current.left  # Сын current меньше родителя current, сый уйдёт в левую ветку        if current.left is not None:            current.left.parent = parent        current.parent = parent.parent        # Назначения current сыном у деда        if parent.parent is None:  # Если деда не было, значит родитель был корнем, делаем current корнем            self.root = current        elif parent == parent.parent.left:            parent.parent.left = current  # Если родитель был левым ребенком то current становится тоже левым ребёнком, иначе правым        else:            parent.parent.right = current        current.left = parent        parent.parent = current    def print_tree(self, node=None, level=0, prefix='Root: '):        if node is None and level == 0:            node = self.root            if node is None:                print("Дерево пустое.")                return        if node.right is not None:            self.print_tree(node.right, level + 1, 'R--> ')        print(' ' * (level * 4) + prefix + str(node.value))        if node.left is not None:            self.print_tree(node.left, level + 1, 'L--> ')tree = Splay_tree()tree.insert(5)tree.insert(7)tree.print_tree()print('----------------')# tree.insert(100)tree.insert(20)tree.print_tree()print('-------------------')tree.insert(50)tree.insert(15)tree.print_tree()